import { randomUUID } from "node:crypto";
import { TokenStore } from "../storage/TokenStore.js";

/** Signs users in and out and checks the tokens it issued. */
export class AuthService {
  constructor(private readonly tokens: TokenStore) {}

  login(user: string, password: string): string {
    if (user === "" || password === "") {
      throw new Error("user and password are required");
    }
    const token = randomUUID();
    this.tokens.save(token, user);
    return token;
  }

  logout(token: string): void {
    this.tokens.remove(token);
  }

  async validateToken(token: string): Promise<boolean> {
    return this.tokens.find(token) !== undefined;
  }
}
